@charset "UTF-8";
@import url("https://googleapis.com");
.accordion-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background-color: #f3f4f6;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-family: sans-serif;
  font-weight: bold;
  font-size: 14px;
  cursor: pointer;
}

.header-actions {
  display: flex;
  align-items: center;
}

.icon {
  display: inline-block;
  transition: transform 0.2s ease;
}

/* Styling für das interaktive Dokumenten-Icon */
.doc-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  color: #4b5563;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s ease;
}

.doc-icon:hover {
  color: #2563eb;
  background-color: #dbeafe;
}

/* 🚨 MERGE: Zwingt den Inhalt, sich an das Appsmith-Widget-Fenster (100% Höhe) anzupassen */
.accordion-content {
  padding: 5px;
  background-color: #ffffff;
  border: 1px solid #e5e7eb;
  border-top: none;
  border-radius: 0 0 6px 6px;
  font-size: 14px;
  line-height: 1.5;
  display: flex;
  flex-direction: column;
  height: calc(100% - 60px); /* Zieht die Kopfzeilen-Höhe ab */
}

/* 🚨 MERGE: Das Editor-Skelett nutzt jetzt automatisch 100% der Höhe */
.pell {
  border: 1px solid #d1d5db;
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  width: 100%;
  flex-grow: 1;
  min-height: 400px;
}

.pell-actionbar {
  background-color: #f9fafb;
  border-bottom: 1px solid #d1d5db;
  display: flex;
  padding: 2px;
  flex-shrink: 0; /* Verhindert das Zusammendrücken */
}

/* Optional: Erzwingen Sie einen Umbruch für eine echte "zweite Leiste" */
.pell-actionbar ::after {
  /* Falls Sie nach einem bestimmten Element gezielt umbrechen wollen */
}

/* Die einzelnen Knöpfe in der Menüleiste */
.pell-button {
  margin-left: 5px;
  margin-right: 5px;
  background-color: transparent;
  border: none;
  cursor: pointer;
  height: 28px;
  min-width: 30px;
  padding: 0 8px;
  font-family: sans-serif;
  font-weight: bold;
  color: #374151;
  border-radius: 3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
}

.pell-button:hover {
  background-color: #e5e7eb;
}

/* Macht den Code-Button optisch markanter, wenn er deaktiviert ist */
.pell-button[disabled] {
  margin-left: 5px;
  margin-right: 5px;
  opacity: 0.4;
  cursor: not-allowed;
  background-color: transparent;
}

/* 🚨 MERGE: Das weiße Textfeld füllt den Platz im Widget jetzt vollständig (100%) aus */
.pell-content {
  outline: 0;
  padding: 12px;
  font-family: sans-serif;
  background-color: #ffffff;
  border-top: none;
  height: 100%;
  flex-grow: 1;
  overflow-y: auto; /* Scrollbalken erscheint automatisch bei viel Text */
  resize: vertical; /* Erlaubt manuelles Ziehen, falls gewünscht */
}

/* Google Fonts laden */
/* Optional: Verhindert, dass unformatierte Buttons das Layout zerreißen */
.pell-actionbar select {
  max-width: 120px;
}

.save-btn {
  background-color: #2563eb;
  color: white;
  border: none;
  padding: 6px 14px;
  border-radius: 4px;
  cursor: pointer;
  font-family: sans-serif;
  font-size: 13px;
  font-weight: bold;
  transition: background 0.2s ease;
}

.save-btn:hover {
  background-color: #1d4ed8;
}

/* Positioniert Speichern-Button links und Mülleimer rechts */
.content-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 15px;
  flex-shrink: 0;
}

/* Styling für den Mülleimer-Button */
.trash-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  background: transparent;
  border: none;
  color: #6b7280;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s ease;
}

.trash-btn:hover {
  color: #dc2626;
  background-color: #fee2e2;
}

/* 🚨 NEU: Macht den Speichern-Button optisch inaktiv, wenn nichts geändert wurde */
.save-btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
  background-color: #9ca3af; /* Wechselt zu einem neutralen Grau */
}

.save-btn[disabled]:hover {
  background-color: #9ca3af; /* Deaktiviert den blauen Hover-Effekt */
}

