const pell = {
  exec: (command, value = null) => document.execCommand(command, false, value),
  init: (settings) => {
    settings.actions = settings.actions || [
      'fontPicker', 'sizePicker', 'colorDropdown', 'heading1', 'heading2', 'paragraph',
      'bold', 'italic', 'underline',
      'olist', 'ulist', 'indent', 'outdent',
      'justifyLeft', 'justifyCenter', 'justifyRight', 'justifyFull',
      'colorPicker',
      'clearFormatting',
      'code',
      'help',
      'trash'
    ];

    const actionbar = document.createElement('div');
    actionbar.className = 'pell-actionbar';
    settings.element.appendChild(actionbar);

    const content = document.createElement('div');
    content.className = 'pell-content';
    content.contentEditable = true;
    content.oninput = (e) => settings.onChange(e.target.innerHTML);
    settings.element.appendChild(content);

    let isCodeMode = false;

    const defActions = {
      'fontPicker': {
        title: `
          <select id="pell-font-dropdown" style="border:none; background:transparent; font-size:14px; cursor:pointer; height:100%;">
            <option value=""></option>
            <option value="Google Sans" style="font-family: 'Google Sans', sans-serif;">Google Sans (Gemini)</option>
            <option value="Google Sans Code" style="font-family: 'Google Sans Code', monospace;">Google Sans Code</option>
            <option value="Arial" style="font-family: Arial, sans-serif;">Arial</option>
            <option value="Courier New" style="font-family: 'Courier New', monospace;">Courier New</option>
            <option value="Georgia" style="font-family: Georgia, serif;">Georgia</option>
            <option value="Times New Roman" style="font-family: 'Times New Roman', serif;">Times New Roman</option>
            <option value="Verdana" style="font-family: Verdana, sans-serif;">Verdana</option>
          </select>
        `,
        result: () => {}
      },

      'sizePicker': {
        title: `
          <select id="pell-size-dropdown" style="border:none; background:transparent; font-size:14px; cursor:pointer; height:100%;">
            <option value="" disabled selected>Größe</option>
            <option value="9pt">9pt</option>
            <option value="10pt">10pt</option>
            <option value="11pt">11pt</option>
            <option value="12pt">12pt</option>
            <option value="13pt">13pt</option>
            <option value="14pt">14pt</option>
            <option value="15pt">15pt</option>
            <option value="16pt">16pt</option>
            <option value="17pt">17pt</option>
            <option value="18pt">18pt</option>
            <option value="19pt">19pt</option>
            <option value="20pt">20pt</option>
          </select>
        `,
        result: () => {}
      },

      'colorDropdown': {
        title: `
          <select id="pell-color-dropdown" style="border:none; background:transparent; font-size:14px; cursor:pointer; height:100%;">
            <option value="" disabled selected>Farbe</option>
            <option value="#000000" style="color:#000000;">Schwarz</option>
            <option value="#374151" style="color:#374151;">Anthrazit</option>
            <option value="#4b5563" style="color:#4b5563;">Grau</option>
            <option value="#dc2626" style="color:#dc2626;">Rot</option>
            <option value="#ea580c" style="color:#ea580c;">Orange</option>
            <option value="#eab308" style="color:#eab308;">Gelb</option>
            <option value="#16a34a" style="color:#16a34a;">Grün</option>
            <option value="#2563eb" style="color:#2563eb;">Blau</option>
            <option value="#4f46e5" style="color:#4f46e5;">Indigo</option>
            <option value="#9333ea" style="color:#9333ea;">Violett</option>
          </select>
        `,
        result: () => {}
      },

      'heading1': {result: () => pell.exec('formatBlock', '<h1>'), title: 'H1'},
      'heading2': {result: () => pell.exec('formatBlock', '<h2>'), title: 'H2'},
      'paragraph': {result: () => pell.exec('formatBlock', '<p>'), title: 'P'},
      bold: {result: () => pell.exec('bold'), title: 'B'},
      italic: {result: () => pell.exec('italic'), title: 'I'},
      underline: {result: () => pell.exec('underline'), title: 'U'},
      olist: {result: () => pell.exec('insertOrderedList'), title: '1.'},
      ulist: {result: () => pell.exec('insertUnorderedList'), title: '•'},
      'outdent': {result: () => pell.exec('outdent'), title: '⬅'},
      'indent': {result: () => pell.exec('indent'), title: '➔'},
      'justifyLeft': {result: () => pell.exec('justifyLeft'), title: '𝌀'},
      'justifyCenter': {result: () => pell.exec('justifyCenter'), title: '𝌁'},
      'justifyRight': {result: () => pell.exec('justifyRight'), title: '𝌂'},
      'justifyFull': {result: () => pell.exec('justifyFull'), title: '𝌃'},

      'colorPicker': {
        title: '<input type="color" id="pell-color-picker" style="width:20px; height:20px; border:none; padding:0; cursor:pointer;" value="#374151">',
        result: () => {}
      },

      'clearFormatting': {
        title: '🧹 Text säubern',
        result: () => {
          pell.exec('removeFormat');
          pell.exec('formatBlock', '<p>');
          setTimeout(() => {
            settings.onChange(content.innerHTML);
          }, 10);
        }
      },

      'code': {
        title: '⚙ Code',
        result: () => {
          isCodeMode = !isCodeMode;

          if (isCodeMode) {
            content.textContent = content.innerHTML;
            content.style.fontFamily = "monospace";
            content.style.backgroundColor = "#f8fafc";
            content.setAttribute("data-mode", "code");

            const buttons = actionbar.querySelectorAll('.pell-button');
            buttons.forEach(btn => {
              if (!btn.innerHTML.includes('Code') && !btn.innerHTML.includes('?') && !btn.innerHTML.includes('🖫') && !btn.innerHTML.includes('🗑')) {
                btn.setAttribute('disabled', 'true');
              }
            });

            const pickerEl = actionbar.querySelector('#pell-color-picker');
            if (pickerEl) pickerEl.setAttribute('disabled', 'true');

            const fontEl = actionbar.querySelector('#pell-font-dropdown');
            if (fontEl) fontEl.setAttribute('disabled', 'true');

            const sizeEl = actionbar.querySelector('#pell-size-dropdown');
            if (sizeEl) sizeEl.setAttribute('disabled', 'true');

            const colorDropdownEl = actionbar.querySelector('#pell-color-dropdown');
            if (colorDropdownEl) colorDropdownEl.setAttribute('disabled', 'true');

          } else {
            content.innerHTML = content.textContent;
            content.style.fontFamily = "'Google Sans', sans-serif";
            content.style.backgroundColor = "#ffffff";
            content.removeAttribute("data-mode");

            const buttons = actionbar.querySelectorAll('.pell-button');
            buttons.forEach(btn => btn.removeAttribute('disabled'));

            const pickerEl = actionbar.querySelector('#pell-color-picker');
            if (pickerEl) pickerEl.removeAttribute('disabled');

            const fontEl = actionbar.querySelector('#pell-font-dropdown');
            if (fontEl) fontEl.removeAttribute('disabled');

            const sizeEl = actionbar.querySelector('#pell-size-dropdown');
            if (sizeEl) sizeEl.removeAttribute('disabled');

            const colorDropdownEl = actionbar.querySelector('#pell-color-dropdown');
            if (colorDropdownEl) colorDropdownEl.removeAttribute('disabled');
          }

          settings.onChange(content.innerHTML);
        }
      },

      'help': {
        title: () => {
          const hasContent = appsmith.model.aiErklaerung && appsmith.model.aiErklaerung.trim() !== "";
          return hasContent ? '🖫' : '?';
        },
        result: () => {
          const hasContent = appsmith.model.aiErklaerung && appsmith.model.aiErklaerung.trim() !== "";
          if (hasContent) {
            appsmith.triggerEvent("onSaveClick");
          } else {
            appsmith.triggerEvent("onDocClick");
          }
        }
      },

      'trash': {
        title: '🗑',
        result: () => {
          appsmith.triggerEvent("onTrashClick");
        }
      }
    };

    settings.actions.forEach(action => {
      const btn = document.createElement('button');
      btn.className = 'pell-button';
      btn.dataset.action = action;

      btn.innerHTML = typeof defActions[action].title === 'function' 
        ? defActions[action].title() 
        : defActions[action].title;

      btn.type = 'button';
      btn.onclick = () => {
        defActions[action].result();
        content.focus();
      };

      // Diskette (help) schiebt sich nach rechts, Mülleimer folgt direkt dahinter
      if (action === 'help') {
        btn.style.marginLeft = 'auto';
      } else if (action === 'trash') {
        btn.style.marginLeft = '2px';
      }

      actionbar.appendChild(btn);
    });

    const picker = actionbar.querySelector('#pell-color-picker');
    if (picker) {
      picker.addEventListener('input', (e) => {
        pell.exec('foreColor', e.target.value);
        content.focus();
      });
    }

    const fontDropdown = actionbar.querySelector('#pell-font-dropdown');
    if (fontDropdown) {
      fontDropdown.addEventListener('change', (e) => {
        if (e.target.value !== "") {
          pell.exec('fontName', e.target.value);
          settings.onChange(content.innerHTML);
        }
        content.focus();
      });
    }

    const sizeDropdown = actionbar.querySelector('#pell-size-dropdown');
    if (sizeDropdown) {
      sizeDropdown.addEventListener('change', (e) => {
        const targetSize = e.target.value;
        const selection = window.getSelection();

        if (selection.rangeCount > 0 && !selection.isCollapsed) {
          const range = selection.getRangeAt(0);
          const span = document.createElement('span');
          span.style.fontSize = targetSize;

          try {
            range.surroundContents(span);
          } catch (err) {
            const clone = range.extractContents();
            const wrapper = document.createElement('span');
            wrapper.style.fontSize = targetSize;
            wrapper.appendChild(clone);
            range.insertNode(wrapper);
          }

          selection.removeAllRanges();
        }

        sizeDropdown.selectedIndex = 0;
        settings.onChange(content.innerHTML);
        content.focus();
      });
    }

    const colorDropdown = actionbar.querySelector('#pell-color-dropdown');
    if (colorDropdown) {
      colorDropdown.addEventListener('change', (e) => {
        pell.exec('foreColor', e.target.value);
        colorDropdown.selectedIndex = 0;
        settings.onChange(content.innerHTML);
        content.focus();
      });
    }

    document.addEventListener('selectionchange', () => {
      if (document.activeElement !== content || isCodeMode) return;
      const selection = window.getSelection();
      if (selection.rangeCount > 0) {
        let node = selection.getRangeAt(0).startContainer;
        if (node.nodeType === 3) {
          node = node.parentNode;
        }
        let foundFont = "";
        while (node && node !== content) {
          if (node.style && node.style.fontFamily) {
            foundFont = node.style.fontFamily.replace(/['"]/g, '').split(',')[0].trim();
            break;
          }
          if (node.nodeName === 'FONT' && node.hasAttribute('face')) {
            foundFont = node.getAttribute('face');
            break;
          }
          node = node.parentNode;
        }
        if (fontDropdown) {
          if (foundFont) {
            let match = false;
            for (let i = 0; i < fontDropdown.options.length; i++) {
              if (fontDropdown.options[i].value.toLowerCase() === foundFont.toLowerCase()) {
                fontDropdown.selectedIndex = i;
                match = true;
                break;
              }
            }
            if (!match) fontDropdown.value = "";
          } else {
            fontDropdown.value = "";
          }
        }
      }
    });

    return { content };
  }
};

const toggleBtn = document.getElementById("toggle-btn");
const contentBox = document.getElementById("content-box");
const arrowIcon = document.getElementById("arrow-icon");
const docIconBtn = document.getElementById("doc-icon-btn");
