appsmith.onModelChange(() => {
  const textAusStore = appsmith.model.aiErklaerung;
  const hasContent = textAusStore && textAusStore.trim() !== "";

  // Diskette / Fragezeichen Button aktualisieren
  const helpBtn = document.querySelector('#pell-editor .pell-actionbar .pell-button[data-action="help"]');
  if (helpBtn) {
    helpBtn.innerHTML = hasContent ? '🖫' : '?';
  }

  // Mülltonnen-Button (rechts neben der Diskette) je nach Inhalt ein- oder ausblenden
  const trashBtn = document.querySelector('#pell-editor .pell-actionbar .pell-button[data-action="trash"]');
  if (trashBtn) {
    trashBtn.style.display = hasContent ? 'inline-block' : 'none';
  }

  if (hasContent) {
    if (textAusStore !== currentHtmlText) {
      currentHtmlText = textAusStore;
      editor.content.removeAttribute("data-mode");
      editor.content.style.fontFamily = "'Google Sans', sans-serif";
      editor.content.style.backgroundColor = "#ffffff";
      editor.content.innerHTML = textAusStore;
    }
    if (arrowIcon) arrowIcon.style.display = "inline-block";
    if (docIconBtn) docIconBtn.style.display = "none";
    if (toggleBtn) toggleBtn.style.cursor = "pointer";
  } else {
    editor.content.innerHTML = "";
    currentHtmlText = "";
    if (arrowIcon) arrowIcon.style.display = "none";
    if (docIconBtn) docIconBtn.style.display = "inline-flex";
    if (toggleBtn) toggleBtn.style.cursor = "default";
  }
  //saveTxtBtn.setAttribute('disabled', 'true');
});
